`},"stdlib/explore":{"views/metric-table.js":`// stdlib/explore: the reactive metric table (ROADMAP 6.34, D-214; "Reactive Metric Table" in the block-authoring design). A table of the
// fed block's output with one aggregate per numeric column; when the block runs again (a scrubbed value, an edit) the new aggregates are
// shown next to the ones before and the cells that changed are marked. Sent: its declared values and the tables of the blocks the author
// named. The aggregate and the precision are controls here and are written back as body lines.
const put = (n, a, kids) => {
  for (const k in a || {}) {
    const v = a[k];
    if (v === false || v == null) continue;
    n.setAttribute(k, v === true ? "" : String(v));
  }
  for (const c of kids) if (c != null) n.append(c);
  return n;
};
const h = (t, a, ...k) => put(document.createElement(t), a, k);
const num = (v) => (typeof v === "number" ? v : typeof v === "string" && v.trim() !== "" ? Number(v) : Number.NaN);
function readTable(api) {
  for (const name of api.dataNames()) {
    const d = api.data(name);
    const t = d?.value;
    if (!t || !Array.isArray(t.columns) || !Array.isArray(t.rows)) continue;
    const cols = t.columns.map((c) => (typeof c === "string" ? c : c && typeof c.name === "string" ? c.name : ""));
    const rows = t.rows.map((r) => (Array.isArray(r) ? r : cols.map((c) => (r ? r[c] : null))));
    return { name, cols, rows, total: t.rows.length };
  }
  return null;
}
const isNumeric = (t, i) => {
  let seen = 0;
  for (const r of t.rows) {
    if (r[i] === null || r[i] === undefined || r[i] === "") continue;
    if (!Number.isFinite(num(r[i]))) return false;
    seen++;
  }
  return seen > 0;
};

